export const ACTION_TOOLS = new Set(['issue_refund', 'issue_store_credit', 'escalate_to_human']);

const ACTION_LABEL = {
  issue_refund: 'refund',
  issue_store_credit: 'store credit',
  escalate_to_human: 'escalation',
};

