      ) {
        return refused(
          tool,
          order,
          'DAMAGE_REQUIRES_ESCALATION',
          `The customer reported damage on order ${order.id}, and its total (${formatCents(order.total_cents)}) is over $200. Policy §5: support must not refund it directly; escalate it to a human agent with escalate_to_human.`,
        );
      }
