function splitClauses(sentence) {
  return sentence
    .split(/;\s*|:\s+|,\s+|\s[-–—]\s|\b(?:but|however|although|though|whereas|instead|while|unfortunately|meanwhile)\b/i)
    .map((c) => c.trim())
