      rx(String.raw`\b(?:i|we)(?:'ve|\s+have)?\s+${ADV}*refunded\b`),
      rx(String.raw`\brefund\s+(?:issued|processed|completed|complete|approved|confirmed|initiated|done|successful|submitted|sent)\b`),
    ],
