.account-chip__label { color: rgba(243, 234, 216, 0.6); font-size: 0.85rem; }
.account-chip strong { color: var(--paper); font-weight: 700; }
.account-chip__out { color: #f2b08f; font-size: 0.85rem; }
.account-chip__out:hover { color: var(--paper); }

