.stamp {
  display: inline-block; font-family: var(--font-mono); font-size: 0.72rem; font-weight: 500;
  letter-spacing: 0.12em; padding: 3px 9px 2px; border-radius: 4px; border: 1.5px solid currentColor;
  transform: rotate(-1.5deg);
}
.stamp--delivered { color: var(--moss); background: rgba(79, 122, 58, 0.08); }
.stamp--refunded { color: var(--slate); background: rgba(61, 90, 115, 0.08); }
.stamp--escalated { color: var(--blaze-deep); background: rgba(226, 98, 43, 0.1); }

.tag {
  display: inline-block; font-size: 0.78rem; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase;
  padding: 3px 10px 3px 14px; color: #fff; background: var(--clay); position: relative;
  clip-path: polygon(8px 0, 100% 0, 100% 100%, 8px 100%, 0 50%);
}

