.balance {
  padding: 22px 26px; margin-bottom: 24px; display: grid; grid-template-columns: auto 1fr; column-gap: 28px; align-items: center;
  background: linear-gradient(135deg, var(--ink) 0%, #284636 100%); color: var(--paper); border-color: var(--ink);
  animation: rise 0.5s 0.06s ease-out both;
}
.balance__label { margin: 0; grid-column: 1 / -1; font-family: var(--font-mono); font-size: 0.75rem; letter-spacing: 0.2em; text-transform: uppercase; color: #9fbf8a; }
.balance__amount { margin: 4px 0 0; font-size: 2.6rem; font-weight: 500; color: #fff; }
.balance__note { margin: 4px 0 0; color: rgba(243, 234, 216, 0.75); font-size: 0.95rem; max-width: 40ch; }
.ledger-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 24px; }
.ledger-block { padding: 6px 0 4px; animation: rise 0.5s 0.12s ease-out both; }
.ledger-block h2 { margin: 14px 16px 4px; font-family: var(--font-display); font-size: 1.3rem; }

/* ---------------------------------------------------------------- sign-in */

.customer-picks { list-style: none; padding: 0; margin: 0; display: grid; gap: 12px; max-width: 520px; }
.customer-pick {
  display: flex; justify-content: space-between; align-items: center; gap: 12px;
  padding: 16px 20px; background: var(--card); border: 1px solid var(--rule); border-left: 6px solid var(--blaze);
