  margin: 0; padding: 12px 14px; font-size: 0.95rem; color: var(--ink-2);
  background: var(--paper-2); border-radius: 12px; border: 1px dashed var(--rule);
}

.msg {
  max-width: 88%; padding: 10px 14px; border-radius: 14px; font-size: 0.97rem;
  white-space: pre-wrap; overflow-wrap: anywhere;
  animation: pop 0.22s ease-out both;
}
.msg--user {
  align-self: flex-end; background: var(--ink); color: var(--paper); border-bottom-right-radius: 4px;
}
.msg--assistant {
  align-self: flex-start; background: #fff; color: var(--ink); border: 1px solid var(--rule);
  border-left: 4px solid var(--blaze); border-bottom-left-radius: 4px;
}
.msg--error { border-left-color: var(--clay); background: #fff4f1; }

.receipts { align-self: flex-start; display: flex; flex-direction: column; gap: 6px; max-width: 88%; animation: pop 0.25s 0.05s ease-out both; }
.receipt {
  font-family: var(--font-mono); font-size: 0.74rem; letter-spacing: 0.02em; line-height: 1.35;
  padding: 6px 10px; border-radius: 6px; background: rgba(79, 122, 58, 0.1); color: var(--moss);
  border: 1px dashed rgba(79, 122, 58, 0.5);
}
.receipt strong { font-weight: 600; text-transform: uppercase; letter-spacing: 0.12em; margin-right: 4px; }

.typing { align-self: flex-start; display: inline-flex; gap: 5px; align-items: center; padding: 12px 14px; color: var(--muted); font-size: 0.85rem; }
.typing i {
  width: 7px; height: 7px; border-radius: 50%; background: var(--blaze); display: inline-block;
  animation: bounce 1s infinite ease-in-out;
}
.typing i:nth-child(2) { animation-delay: 0.15s; }
.typing i:nth-child(3) { animation-delay: 0.3s; }
.typing span { margin-left: 6px; }

.chat__form { display: flex; gap: 8px; padding: 12px; border-top: 1px solid var(--rule); background: var(--paper-2); }
.chat__form textarea {
  flex: 1; resize: none; min-height: 46px; max-height: 140px; padding: 10px 12px;
  font: inherit; font-size: 0.97rem; color: var(--ink); background: #fff;
  border: 1px solid var(--rule); border-radius: 10px; outline: none;
}
.chat__form textarea:focus { border-color: var(--ink-2); box-shadow: 0 0 0 3px rgba(226, 98, 43, 0.2); }
.chat__send {
  align-self: stretch; padding: 0 18px; border: 0; border-radius: 10px; cursor: pointer;
  font: inherit; font-weight: 700; color: #fff; background: var(--blaze);
  transition: background-color 0.15s, transform 0.1s;
}
.chat__send:hover:not(:disabled) { background: var(--blaze-deep); }
.chat__send:active:not(:disabled) { transform: translateY(1px); }
.chat__send:disabled, .chat__form textarea:disabled { opacity: 0.55; cursor: not-allowed; }
.chat__fineprint { margin: 0; padding: 0 14px 12px; font-size: 0.78rem; color: var(--muted); background: var(--paper-2); }

/* ---------------------------------------------------------------- footer */

.site-footer { border-top: 1px solid var(--rule); color: var(--muted); font-size: 0.85rem; }
.site-footer p { max-width: 1320px; margin: 0 auto; padding: 18px 28px; }

