@keyframes rise { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
@keyframes pop { from { opacity: 0; transform: translateY(4px) scale(0.98); } to { opacity: 1; transform: none; } }
@keyframes bounce { 0%, 80%, 100% { transform: translateY(0); opacity: 0.5; } 40% { transform: translateY(-4px); opacity: 1; } }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}

/* ---------------------------------------------------------------- responsive */

@media (max-width: 1040px) {
  .shell { grid-template-columns: 1fr; }
  .chat { position: static; max-height: none; }
  .ledger-grid { grid-template-columns: 1fr; }
}

@media (max-width: 680px) {
  .site-header__inner { flex-wrap: wrap; gap: 12px; padding: 12px 18px; }
  .account-chip { margin-left: 0; width: 100%; }
  .shell { padding: 24px 16px 36px; }
  .data-table thead { display: none; }
  .data-table tr { display: block; padding: 10px 0; border-bottom: 1px dashed var(--rule); }
  .data-table td { display: flex; justify-content: space-between; gap: 12px; border: 0; padding: 6px 16px; text-align: right; }
  .data-table td::before { content: attr(data-label); font-family: var(--font-mono); font-size: 0.7rem; letter-spacing: 0.12em; text-transform: uppercase; color: var(--muted); text-align: left; }
  .data-table .empty { display: block; text-align: center; }
  .data-table .empty::before { content: none; }
  .balance { grid-template-columns: 1fr; }
}

