.account-chip__out { color: #f2b08f; font-size: 0.85rem; }
.account-chip__out:hover { color: var(--paper); }

/* ---------------------------------------------------------------- layout */

.shell {
  flex: 1;
  width: 100%; max-width: 1320px; margin: 0 auto; padding: 36px 28px 48px;
