  text-transform: uppercase; color: var(--blaze-deep);
}
.page-head h1, .hero h1 {
  margin: 0; font-family: var(--font-display); font-weight: 700; line-height: 1.05;
  font-size: clamp(2rem, 3.2vw, 2.9rem); letter-spacing: -0.01em;
}
.lede { margin: 10px 0 24px; color: var(--ink-2); max-width: 62ch; }
.page-head, .hero { animation: rise 0.5s ease-out both; }

.card {
  background: var(--card);
  border: 1px solid var(--rule);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

/* ---------------------------------------------------------------- tables */

.table-wrap { overflow-x: auto; animation: rise 0.5s 0.08s ease-out both; }
.data-table { width: 100%; border-collapse: collapse; font-size: 0.98rem; }
.data-table th {
  text-align: left; font-family: var(--font-mono); font-weight: 500; font-size: 0.72rem;
  letter-spacing: 0.14em; text-transform: uppercase; color: var(--muted);
  padding: 14px 16px; border-bottom: 2px solid var(--ink); white-space: nowrap;
}
.data-table td { padding: 14px 16px; border-bottom: 1px dashed var(--rule); vertical-align: middle; }
.data-table tbody tr:last-child td { border-bottom: 0; }
.data-table tbody tr { animation: rise 0.45s ease-out both; animation-delay: calc(0.12s + var(--i, 0) * 0.06s); }
.data-table tbody tr:hover td { background: rgba(232, 223, 203, 0.45); }
.data-table .num { text-align: right; }
.order-id { font-weight: 500; color: var(--ink); }
.empty { color: var(--muted); font-style: italic; text-align: center; padding: 28px; }

.stamp {
  display: inline-block; font-family: var(--font-mono); font-size: 0.72rem; font-weight: 500;
