  padding: 3px 10px 3px 14px; color: #fff; background: var(--clay); position: relative;
  clip-path: polygon(8px 0, 100% 0, 100% 100%, 8px 100%, 0 50%);
}

/* ---------------------------------------------------------------- ledger */

.balance {
  padding: 22px 26px; margin-bottom: 24px; display: grid; grid-template-columns: auto 1fr; column-gap: 28px; align-items: center;
  background: linear-gradient(135deg, var(--ink) 0%, #284636 100%); color: var(--paper); border-color: var(--ink);
