const CREDIT = String.raw`credit(?!\s*card)(?!\s*or\s+debit)\b`;
const HUMAN = String.raw`(?:human|agent|specialist|team|supervisor|manager|colleague|representative|staff|person|teammate)s?`;

const rx = (s) => new RegExp(s, 'i');

