// Drive the real chat widget in Chrome against an in-process server + real Ollama.
import { chromium } from 'playwright-core';

const PROJECT = '/home/mdlog/Project-MDlabs/Luma/kanecli-online-hackathon/saydo/target';
const { openDb } = await import(`${PROJECT}/src/db.js`);
const { seed } = await import(`${PROJECT}/src/seed.js`);
const { createApp } = await import(`${PROJECT}/src/app.js`);
const { loadConfig } = await import(`${PROJECT}/src/assistant.js`);

const db = openDb(':memory:');
seed(db);
const app = createApp(db, { config: loadConfig({ ...process.env, OLLAMA_MODEL: process.env.OLLAMA_MODEL || 'gpt-oss:20b' }) });
const server = await new Promise((r) => { const s = app.listen(0, () => r(s)); });
const base = `http://127.0.0.1:${server.address().port}`;

const browser = await chromium.launch({ executablePath: '/usr/bin/google-chrome', headless: true });
const page = await browser.newPage({ viewport: { width: 1360, height: 900 } });
const chatBodies = [];
page.on('request', (req) => { if (req.url().endsWith('/api/chat')) chatBodies.push(JSON.parse(req.postData())); });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });

const check = (cond, msg) => { console.log(`${cond ? 'PASS' : 'FAIL'}  ${msg}`); if (!cond) process.exitCode = 1; };

await page.goto(`${base}/login-as/cust-ana`);
check(new URL(page.url()).pathname === '/orders', `redirected to /orders (${page.url()})`);
check((await page.textContent('#signed-in-customer')).trim() === 'Ana Lima', 'header shows Ana Lima');
check((await page.locator('#orders-table tbody tr').count()) === 4, '4 order rows');
await page.screenshot({ path: '/tmp/trailhead-e2e/orders.png', fullPage: true });

const complete = page.locator('.msg--assistant[data-reply-complete="true"]');
await page.fill('#chat-input', 'Hi, please refund my running vest, order 1043. I changed my mind.');
await page.keyboard.press('Enter');
await page.waitForSelector('.typing', { timeout: 5000 });
check((await page.locator('.msg--assistant').count()) === 0, 'no assistant bubble while the reply is pending');
await complete.first().waitFor({ timeout: 180000 });
console.log('  reply 1:', (await complete.nth(0).textContent()).trim());
check((await page.locator('.typing').count()) === 0, 'typing indicator removed');
check((await page.locator('.receipt[data-action-type="refund"]').count()) === 1, 'refund receipt shown');
await page.waitForFunction(() => document.querySelector('tr[data-order-id="1043"] [data-status]')?.dataset.status === 'REFUNDED', null, { timeout: 5000 }).then(
  () => check(true, 'orders table refreshed: 1043 REFUNDED'),
  () => check(false, 'orders table refreshed: 1043 REFUNDED'),
);

await page.fill('#chat-input', 'Thanks! And can I return my hiking boots too, order 1042?');
await page.click('#chat-send');
await complete.nth(1).waitFor({ timeout: 180000 });
console.log('  reply 2:', (await complete.nth(1).textContent()).trim());
check(chatBodies.length === 2 && chatBodies[1].messages.length === 3, `turn 2 sent full history (${chatBodies[1]?.messages.map((m) => m.role).join(',')})`);
await page.screenshot({ path: '/tmp/trailhead-e2e/chat.png', fullPage: true });

await page.goto(`${base}/account/ledger`);
check((await page.locator('#refunds-table tbody tr[data-order-id="1043"]').count()) === 1, 'ledger lists the 1043 refund');
check((await page.textContent('#store-credit-balance')).trim() === '$0.00', 'store-credit balance $0.00');
check((await page.locator('#support-chat').count()) === 1, 'chat widget on ledger page');
await page.screenshot({ path: '/tmp/trailhead-e2e/ledger.png', fullPage: true });

await page.setViewportSize({ width: 420, height: 900 });
await page.goto(`${base}/orders`);
await page.screenshot({ path: '/tmp/trailhead-e2e/mobile.png', fullPage: true });

check(errors.length === 0, `no page errors ${errors.join(' | ')}`);
await browser.close();
server.close();

