// Start the real server with `npm start`, check /login-as/cust-ana and /orders, then stop it.
import { spawn } from 'node:child_process';

const PROJECT = '/home/mdlog/Project-MDlabs/Luma/kanecli-online-hackathon/saydo/target';
const base = 'http://localhost:3000';

try {
  await fetch(base, { signal: AbortSignal.timeout(1000) });
  console.log('Port 3000 is already in use; aborting.');
  process.exit(2);
} catch {
  /* free */
}

const child = spawn('npm', ['start'], { cwd: PROJECT, stdio: ['ignore', 'pipe', 'pipe'], detached: true });
let log = '';
child.stdout.on('data', (d) => { log += d; });
child.stderr.on('data', (d) => { log += d; });

const ready = await new Promise((resolve) => {
  const t0 = Date.now();
  const tick = setInterval(() => {
    if (log.includes('running at')) { clearInterval(tick); resolve(true); }
    else if (Date.now() - t0 > 20000 || child.exitCode !== null) { clearInterval(tick); resolve(false); }
  }, 100);
});
console.log('--- server output ---\n' + log.trim() + '\n---------------------');
let ok = ready;
if (ready) {
  const login = await fetch(`${base}/login-as/cust-ana`, { redirect: 'manual' });
  const cookie = (login.headers.get('set-cookie') || '').split(';')[0];
  console.log(`GET /login-as/cust-ana -> ${login.status} Location: ${login.headers.get('location')} Set-Cookie: ${cookie}`);
  ok &&= login.status === 302 && login.headers.get('location') === '/orders' && cookie === 'customer_id=cust-ana';

  const orders = await fetch(`${base}/orders`, { headers: { cookie } });
  const page = await orders.text();
  const ids = [...page.matchAll(/<tr data-order-id="(\d+)"/g)].map((m) => m[1]);
  const days = [...page.matchAll(/data-days-since-delivery="(\d+)"/g)].map((m) => m[1]);
  const statuses = [...page.matchAll(/data-status="([A-Z]+)"/g)].map((m) => m[1]);
  const signedIn = page.match(/id="signed-in-customer"[^>]*>([^<]+)</)?.[1];
  console.log(`GET /orders -> ${orders.status}; signed in as: ${signedIn}; orders: ${ids.join(', ')}; days since delivery: ${days.join(', ')}; statuses: ${statuses.join(', ')}; final-sale tag: ${page.includes('tag--final')}; chat widget: ${page.includes('id="support-chat"')}`);
  ok &&= orders.status === 200 && signedIn === 'Ana Lima' && ids.join() === '1045,1044,1043,1042' && days.join() === '3,5,10,45';

  const ledger = await fetch(`${base}/account/ledger`, { headers: { cookie } });
  console.log(`GET /account/ledger -> ${ledger.status}`);
  ok &&= ledger.status === 200;
}

process.kill(-child.pid, 'SIGTERM');
await new Promise((r) => child.on('exit', r));
let stillUp = true;
try { await fetch(base, { signal: AbortSignal.timeout(1000) }); } catch { stillUp = false; }
console.log(`server stopped: ${!stillUp}`);
console.log(ok && !stillUp ? 'SMOKE CHECK PASSED' : 'SMOKE CHECK FAILED');
process.exit(ok && !stillUp ? 0 : 1);

