/** Local calendar date (YYYY-MM-DD) of an ISO timestamp. */
export function isoToLocalDate(iso) {
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? String(iso).slice(0, 10) : localDateString(d);
}
EOF
